  require (forall Z. (Z ~= n & Z ~= next) -> btw(n, next, Z));
  require pending(v, n);

  pending(v, n) := *;	# message may or may not be removed, nothing is sent
  if v = idn(n) {
    leader(n) := true;
  }
  else {
    if le(idn(n), v) {
      pending(v, next) := true;	# forward v to next
    }
  }
}

