invariant depends_tx(TX2, K, T3) -> write_tx(T3, K)

invariant depends_tx(TX2, K, T3) -> commit_tx(T3)

invariant depends_tx(TX2, K, T3) -> le(T3, TX2)

invariant (commit_tx(TX1) & op_in_tx(TX1, O) & op_node(O, N)) -> precommit_tx(TX1, N)

