    require pending(idn(n), n);
    leader(n) := true;
}

action receive(n: node, m: id, n1: node) = {
    require pending(m, n);
    require n ~= n1 & ((Z ~= n & Z ~= n1) -> ring.btw(n, n1, Z));
#    require m ~= idn(n);
    if le(idn(n), m) {
        pending(m, n1) := true;
    };
}

