# Intersection properties
#
################################################################################

# B( ~fa & ~fc & ~fs & ~fi )
axiom exists B:quorum_b. forall N:node. member_b(N, B) -> ~member_fa(N) & ~member_fc(N) & ~member_fs(N) & ~member_fi(N)

