action receive_init(n:node) = {
	require rcv_init(n);

	sent_msg(n, D) := true;
	sent_msg_proj(n) := true;
}

action receive_msg(n:node, s:node) = {
	require sent_msg(s, n);

	rcv_msg(s, n) := true;
