	rcv_msg(s, n) := true;
	accept(n) := accept(n) | chosenAtB(n);
	sent_msg(n, D) := sent_msg(n, D) | (nondet & chosenAtA(n));
	sent_msg_proj(n) := sent_msg_proj(n) | (nondet & chosenAtA(n));
