	require member_fi(n);
	require sent_msg(s, n);

	rcv_msg(s, n) := true;
	accept(n) := accept(n) | chosenAtB(n);
	sent_msg_proj(n) := sentMsgAt(n) | (nondet & chosenAtA(n));
	sent_msg(n, D) := sent_msg(n, D) | (nondet & chosenAtA(n));
}

################################################################################
