invariant [safety_mutex] pc3(T1) & pc3(T2) -> T1 = T2

invariant m(T1, K) & m(T2, K) & (pc2(T1) | pc3(T1)) & (pc2(T2) | pc3(T2)) -> T1 = T2
invariant ~(pc1(T) & pc2(T))
invariant ~(pc1(T) & pc3(T))
invariant ~(pc2(T) & pc3(T))

